/// `YYYY-MM-DD` plus `n` days.
pub fn add_days(iso: &str, n: i64) -> String {
    match crate::session::epoch_seconds(&format!("{iso}T00:00:00Z")) {
        Some(secs) => crate::session::iso_from_epoch(secs + n * 86_400)[..10].to_string(),
        // A date this cannot parse is returned untouched rather than turned into the epoch — a
        // silently-1970 obligation would sort to the front of every calendar.
        None => iso.to_string(),
    }
}
